pub fn differentiate (&self) -> Polynomial<T> {
    let mut coef_diff = Vec::with_capacity(self.degree());
    for (i, &c) in self.coef.iter().enumerate().skip(1) {
        coef_diff.push(c * T::from_usize(i).unwrap());
    }
    Polynomial::from_coef(coef_diff)
}

